package io.github.jesterportfolio.hearth.survival.enchants;
import java.util.*;import java.util.function.*;
import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.inventory.*;import org.bukkit.event.*;import org.bukkit.event.inventory.*;import org.bukkit.event.player.*;import org.bukkit.command.CommandSender;import org.bukkit.configuration.file.YamlConfiguration;
import net.kyori.adventure.text.Component;
/** 가상 UI만 사용한다. 실제 물품·난수는 최종 확인과 native transaction이 소유한다. */
public final class EnchantMenus implements Listener,AutoCloseable {
    private final EnchantRuntime r;private boolean closed;
    private record Input(Player player,Object token,long generation,Consumer<String> apply){}
    private final Map<UUID,Input> inputs=new java.util.concurrent.ConcurrentHashMap<>();
    @FunctionalInterface private interface Action{void run()throws Exception;}
    private final class Screen implements InventoryHolder {final Player p;final Object token;final long generation;final Inventory inventory;boolean admin;final Map<Integer,Action> actions=new HashMap<>();Screen(Player p,String title){this.p=p;token=r.rpg.runtime.sessionToken(p);generation=r.catalog.snapshot().generation();inventory=Bukkit.createInventory(this,54,Component.text(title));}public Inventory getInventory(){return inventory;}}
    public EnchantMenus(EnchantRuntime r){this.r=r;Bukkit.getPluginManager().registerEvents(this,r.rpg.plugin);}
    private boolean current(Screen s){return !closed&&(!s.admin||s.p.hasPermission("hearth.enchants.admin"))&&r.rpg.runtime.current(s.p,s.token)&&r.rpg.available(s.p)&&s.generation==r.catalog.snapshot().generation()&&s.p.getOpenInventory().getTopInventory()==s.inventory;}
    private void button(Screen s,int index,Material icon,String name,List<String> lore,Action action){var item=new ItemStack(icon);item.editMeta(m->{m.displayName(Component.text(name));m.lore(lore.stream().map(Component::text).toList());});s.inventory.setItem(index,item);if(action!=null)s.actions.put(index,action);}
    private void show(Screen s){s.p.openInventory(s.inventory);}
    public void main(Player p){var s=new Screen(p,"특수 인챈트");button(s,10,Material.ENCHANTED_BOOK,"장비에 적용",List.of("책 → 장비 → 보호/증가 재료 → 최종 확인"),()->select(p,EnchantOperations.Action.APPLY,-1,null));button(s,12,Material.ANVIL,"동일 책 합성",List.of("동일 ID·동일 레벨 2개 → 다음 레벨 1개"),()->select(p,EnchantOperations.Action.FUSE,-1,null));button(s,14,Material.SHEARS,"선택 인챈트 회수",List.of("성공: 같은 레벨 책", "실패: 선택한 인챈트만 소멸"),()->select(p,EnchantOperations.Action.EXTRACT,-1,null));button(s,16,Material.BOOK,"책 감정",List.of("이미 정해진 책의 정보를 공개합니다."),()->select(p,EnchantOperations.Action.IDENTIFY,-1,null));button(s,31,Material.PAPER,"최근 결과 기록",List.of("본인 확정 PG 기록 20개"),()->r.store.history(r.rpg.runtime.economy().context(p)).thenAcceptAsync(history->{if(r.rpg.runtime.current(p,s.token)){var screen=new Screen(p,"인챈트 결과 기록");int i=0;for(var line:history)button(screen,i++,Material.PAPER,line,List.of(),null);show(screen);}},r.rpg.owner));if(p.hasPermission("hearth.enchants.admin"))button(s,49,Material.COMMAND_BLOCK,"관리자 설정",List.of("YAML과 같은 정본·검증 후 변경"),()->admin(p,0));show(s);}
    private void select(Player p,EnchantOperations.Action action,int first,String id){var s=new Screen(p,"원본 슬롯 선택 · "+action);var inventory=p.getInventory();for(int n=0;n<41;n++){var item=inventory.getItem(n);if(item==null||item.isEmpty())continue;int index=n;s.inventory.setItem(n,item.clone());s.actions.put(n,()->{if(first<0){if(action==EnchantOperations.Action.EXTRACT){chooseExtract(p,index);return;}var book=r.items.book(p.getInventory().getItem(index)).orElseThrow();if(action==EnchantOperations.Action.IDENTIFY){confirm(p,action,index,-1,book.id(),-1,-1);return;}select(p,action,index,book.id());}else if(action==EnchantOperations.Action.APPLY)auxiliary(p,first,index,id,-1,-1);else confirm(p,action,first,index,id,-1,-1);});}show(s);}
    private void chooseExtract(Player p,int index){var s=new Screen(p,"회수할 인챈트 선택");int n=0;for(var enchant:r.items.read(p.getInventory().getItem(index)).entrySet()){String id=enchant.getKey();button(s,n++,Material.ENCHANTED_BOOK,id+" · "+enchant.getValue(),List.of("다른 인챈트/강화/메타데이터는 보존"),()->confirm(p,EnchantOperations.Action.EXTRACT,index,-1,id,-1,-1));}show(s);}
    private void auxiliary(Player p,int first,int second,String id,int protection,int boost){var s=new Screen(p,"보호/성공률 재료 선택");for(int n=0;n<36;n++){int slot=n;if(slot==first||slot==second)continue;var item=p.getInventory().getItem(n);var book=r.items.book(item);if(book.isEmpty())continue;if(book.get().kind()==EnchantItems.Kind.PROTECTION||book.get().kind()==EnchantItems.Kind.BOOST){s.inventory.setItem(n,item.clone());s.actions.put(n,()->auxiliary(p,first,second,id,book.get().kind()==EnchantItems.Kind.PROTECTION?slot:protection,book.get().kind()==EnchantItems.Kind.BOOST?slot:boost));}}button(s,49,Material.LIME_DYE,"선택 완료",List.of("보호 슬롯 "+protection,"증가 재료 슬롯 "+boost,"선택하지 않은 보조 재료는 소비하지 않습니다."),()->confirm(p,EnchantOperations.Action.APPLY,first,second,id,protection,boost));show(s);}
    private void confirm(Player p,EnchantOperations.Action action,int first,int second,String id,int protection,int boost){var s=new Screen(p,"확률·비용 최종 확인");var snapshot=r.rpg.runtime.economy().capture(p);var req=new EnchantOperations.Request(UUID.randomUUID(),action,first,second,id,protection,boost,s.generation);var definition=Objects.requireNonNull(r.catalog.snapshot().definitions().get(id));var rules=r.rules(action,id);int level=action==EnchantOperations.Action.EXTRACT?r.items.read(p.getInventory().getItem(first)).getOrDefault(id,0):r.items.book(p.getInventory().getItem(first)).orElseThrow().level();var vars=Map.of("level",(double)level);double chance=Math.clamp(rules.success().evaluate(vars),0,1);if(action==EnchantOperations.Action.APPLY){chance*=r.items.book(p.getInventory().getItem(first)).orElseThrow().success();if(boost>=0)chance=Math.min(1,chance+r.items.book(p.getInventory().getItem(boost)).orElseThrow().boost());}double destroy=action==EnchantOperations.Action.APPLY?rules.destroy().evaluate(vars)*r.items.book(p.getInventory().getItem(first)).orElseThrow().destroy():0;button(s,22,Material.PAPER,definition.name()+" "+level+" · "+action,List.of("성공 "+Math.round(chance*100)+"% · 실패 시 장비 파괴 "+Math.round(destroy*100)+"%","비용 "+rules.cost().evaluate(vars),"재료 "+rules.materials(),"합성 실패 정책 "+rules.failure(),"회수 실패는 선택 인챈트만 소멸","요청 "+req.id()),null);button(s,30,Material.LIME_DYE,"확정",List.of("현재 슬롯·정책을 다시 검사한 뒤 실행"),()->{if(!r.rpg.runtime.economy().capture(p).equals(snapshot))throw new IllegalStateException("원본 슬롯이 바뀌었습니다.");r.execute(p,req);});button(s,32,Material.BARRIER,"취소",List.of("소지품은 화면으로 옮기지 않았습니다."),p::closeInventory);show(s);}
    public void admin(Player p,int page){if(!p.hasPermission("hearth.enchants.admin"))return;var s=new Screen(p,"인챈트 관리자 · "+(page+1));s.admin=true;var defs=new ArrayList<>(r.catalog.snapshot().definitions().values());defs.sort(Comparator.comparing(EnchantDefinition::id));for(int n=0;n<45&&page*45+n<defs.size();n++){var d=defs.get(page*45+n);button(s,n,Material.ENCHANTED_BOOK,d.id(),List.of("활성 "+d.enabled(),"최대 레벨 "+d.maxLevel()),()->definition(p,d.id()));}button(s,45,Material.ARROW,"이전",List.of(),()->admin(p,Math.max(0,page-1)));button(s,53,Material.ARROW,"다음",List.of(),()->admin(p,Math.min((defs.size()-1)/45,page+1)));button(s,47,Material.PAPER,"신규 생성",List.of("기존 정의를 템플릿으로 복제, 기본 비활성"),()->ask(p,s.generation,text->{r.catalog.create(text,defs.getFirst().id());admin(p,0);}));button(s,49,Material.REDSTONE,"안전한 리로드",List.of("오류면 기존 세대 보존"),()->{r.reload();admin(p,page);});button(s,50,Material.COMPARATOR,"공통 비용·확률·개수",List.of("operations.yml과 같은 정본"),()->ask(p,s.generation,text->{String[] parts=text.split(" ",2);r.editOperation(parts[0],parts[1]);admin(p,page);}));show(s);}
    private void definition(Player p,String id){var s=new Screen(p,id);s.admin=true;var d=r.catalog.snapshot().definitions().get(id);int n=0;for(String key:List.of("name","enabled","max-level","equipment","slots","conflicts","worlds","operations")){String field=key;button(s,n++,Material.PAPER,key,List.of(String.valueOf(d.document().getOrDefault(key,"미설정")),"클릭 후 YAML 값 입력"),()->ask(p,s.generation,text->{Object parsed=value(text);r.catalog.edit(id,s.generation,y->y.set(field,parsed));definition(p,id);}));}for(int index=0;index<d.rules().size();index++){int rule=index;button(s,18+index,Material.BOOK,"규칙 "+index+" · "+d.rules().get(index).trigger(),List.of("Trigger/Condition/Chance/Cooldown/Duration/Effects"),()->rule(p,id,rule));}button(s,49,Material.CRAFTING_TABLE,"복제",List.of("새 hearth:ID 입력, 원본 보존"),()->ask(p,s.generation,text->{r.catalog.create(text,id);definition(p,text);}));show(s);}
    @SuppressWarnings("unchecked") private void rule(Player p,String id,int index){var s=new Screen(p,"규칙 "+index);s.admin=true;int n=0;var raw=(List<Map<String,Object>>)r.catalog.snapshot().definitions().get(id).document().get("rules");for(String field:List.of("trigger","condition","chance","cooldown","duration","effects")){button(s,n++,Material.PAPER,field,List.of(String.valueOf(raw.get(index).get(field)),field.equals("effects")?"효과 맵의 YAML/JSON 목록 입력":"클릭 후 값 입력"),()->ask(p,s.generation,text->{Object parsed=value(text);r.catalog.edit(id,s.generation,y->{var list=y.getMapList("rules");((Map<String,Object>)list.get(index)).put(field,parsed);y.set("rules",list);});rule(p,id,index);}));}button(s,18,Material.BOOK,"전체 효과 목록/조합",new ArrayList<>(r.effects.types()),null);button(s,49,Material.ARROW,"이전",List.of(),()->definition(p,id));show(s);}
    @FunctionalInterface private interface Edit {void accept(String text)throws Exception;}
    private void ask(Player p,long generation,Edit edit){p.closeInventory();inputs.put(p.getUniqueId(),new Input(p,r.rpg.runtime.sessionToken(p),generation,text->{try{edit.accept(text);}catch(Exception e){p.sendMessage(Component.text("설정을 적용하지 않았습니다: "+e.getMessage()));}}));p.sendMessage(Component.text("관리 값 입력 · YAML/JSON 한 줄 (취소: cancel). 파일 편집 후 /인챈트 reload도 가능합니다."));}
    @EventHandler(priority=EventPriority.LOWEST) public void chat(AsyncPlayerChatEvent e){var input=inputs.remove(e.getPlayer().getUniqueId());if(input==null)return;e.setCancelled(true);String text=e.getMessage();if(text.equalsIgnoreCase("cancel")||text.length()>8192)return;Bukkit.getScheduler().runTask(r.rpg.plugin,()->{if(input.player().hasPermission("hearth.enchants.admin")&&r.rpg.runtime.current(input.player(),input.token())&&r.catalog.snapshot().generation()==input.generation())input.apply().accept(text);});}
    private static Object value(String text)throws Exception{var y=new YamlConfiguration();y.loadFromString("value: "+text);Object result=y.get("value");if(result instanceof org.bukkit.configuration.ConfigurationSection s)return s.getValues(false);return result;}
    public void adminCommand(CommandSender sender,String[] args)throws Exception{switch(args[0]){case "admin","관리자"->{if(sender instanceof Player p)admin(p,0);}case "reload"->{r.reload();sender.sendMessage(Component.text("검증한 설정 세대 "+r.catalog.snapshot().generation()));}case "create","clone"->{r.catalog.create(args[1],args.length>2?args[2]:r.catalog.snapshot().definitions().keySet().iterator().next());}case "set"->{String id=args[1],path=args[2];if(!Set.of("name","enabled","max-level","equipment","slots","conflicts","worlds","rules","operations").contains(path))throw new IllegalArgumentException("수정 가능한 정본 필드가 아닙니다.");Object v=value(String.join(" ",Arrays.copyOfRange(args,3,args.length)));r.catalog.edit(id,r.catalog.snapshot().generation(),y->y.set(path,v));}case "give"->{Player target=Objects.requireNonNull(Bukkit.getPlayerExact(args[1]));String id=args[2];var d=Objects.requireNonNull(r.catalog.snapshot().definitions().get(id));int level=Integer.parseInt(args[3]);if(level<1||level>d.maxLevel())throw new IllegalArgumentException("최대 레벨 초과");var kind=args.length>4?EnchantItems.Kind.valueOf(args[4].toUpperCase(Locale.ROOT)):EnchantItems.Kind.BOOK;double success=args.length>5?Double.parseDouble(args[5]):1,destroy=args.length>6?Double.parseDouble(args[6]):0,boost=args.length>7?Double.parseDouble(args[7]):0;r.grant(target,new EnchantItems.Book(id,level,success,destroy,kind,boost));}case "verify"->{io.github.jesterportfolio.hearth.verification.EnchantVerification.run(r.rpg.plugin,r,args[1]).whenComplete((v,e)->r.rpg.plugin.getLogger().log(e==null?java.util.logging.Level.INFO:java.util.logging.Level.SEVERE,"HEARTH_ENCHANT_PROBE "+(e==null?"PASS ":"FAIL ")+args[1],e));}default->throw new IllegalArgumentException("admin|reload|create|clone|set|give|verify");}}
    @EventHandler(priority=EventPriority.HIGHEST) public void click(InventoryClickEvent e){if(!(e.getView().getTopInventory().getHolder() instanceof EnchantMenus.Screen s))return;boolean cancelled=e.isCancelled();e.setCancelled(true);if(cancelled||!current(s)||e.getWhoClicked()!=s.p||e.getClickedInventory()!=s.inventory||e.getClick()!=ClickType.LEFT||!s.p.getItemOnCursor().isEmpty())return;var action=s.actions.get(e.getSlot());if(action!=null)Bukkit.getScheduler().runTask(r.rpg.plugin,()->{if(current(s))try{action.run();}catch(Exception error){s.p.sendMessage(Component.text("요청을 적용하지 않았습니다: "+error.getMessage()));}});}
    @EventHandler(priority=EventPriority.HIGHEST) public void drag(InventoryDragEvent e){if(e.getView().getTopInventory().getHolder() instanceof EnchantMenus.Screen)e.setCancelled(true);}
    @EventHandler public void quit(PlayerQuitEvent e){inputs.remove(e.getPlayer().getUniqueId());}
    public void close(){closed=true;inputs.clear();HandlerList.unregisterAll(this);}
}
